import test from 'node:test';import assert from 'node:assert/strict';
const api=await import('../src/reference-worker-client.mjs').catch(()=>({}));
class FakeWorker{constructor(){this.terminated=false;}postMessage(m){if(m.kind==='boot')queueMicrotask(()=>this.onmessage({data:{kind:'ready'}}));else if(m.kind==='render')queueMicrotask(()=>this.onmessage({data:{kind:'result',id:m.id,result:{value:m.job.n}}}));}terminate(){this.terminated=true;}}
test('worker client pairs result IDs and labels real worker execution',async()=>{assert.equal(typeof api.ReferenceRenderClient,'function');const w=new FakeWorker(),c=new api.ReferenceRenderClient({}, {workerFactory:()=>w});const r=await c.run({n:7});assert.equal(r.value,7);assert.equal(r.execution.mode,'worker');c.dispose();assert.ok(w.terminated);});
test('unavailable worker uses explicit fallback and captures why',async()=>{assert.equal(typeof api.ReferenceRenderClient,'function');const c=new api.ReferenceRenderClient({}, {workerFactory:()=>{throw Error('CSP forbids worker');},fallbackFactory:()=>({render:async job=>({value:job.n}),dispose(){}})});const r=await c.run({n:9});assert.equal(r.value,9);assert.equal(r.execution.mode,'main-thread-fallback');assert.match(r.execution.warnings.join(' '),/CSP/);c.dispose();});
test('worker failure in flight retries same accepted job in fallback, without a hung promise',async()=>{assert.equal(typeof api.ReferenceRenderClient,'function');const w=new FakeWorker();w.postMessage=function(m){if(m.kind==='boot')queueMicrotask(()=>this.onmessage({data:{kind:'ready'}}));else queueMicrotask(()=>this.onerror({message:'crash',preventDefault(){}}));};const seen=[],c=new api.ReferenceRenderClient({}, {workerFactory:()=>w,fallbackFactory:()=>({render:async j=>{seen.push(j.n);return {value:j.n};},dispose(){}})});const r=await c.run({n:13});assert.equal(r.value,13);assert.deepEqual(seen,[13]);assert.equal(r.execution.mode,'main-thread-fallback');assert.ok(w.terminated);c.dispose();});
test('render errors are surfaced, not disguised as worker failure or a fallback sky',async()=>{assert.equal(typeof api.ReferenceRenderClient,'function');const w=new FakeWorker();w.postMessage=function(m){queueMicrotask(()=>this.onmessage({data:m.kind==='boot'?{kind:'ready'}:{kind:'error',id:m.id,error:'invalid observer'}}));};const c=new api.ReferenceRenderClient({}, {workerFactory:()=>w,fallbackFactory:()=>{throw Error('fallback not allowed');}});await assert.rejects(()=>c.run({}),/invalid observer/);assert.equal(c.mode,'worker');c.dispose();});
test('worker startup timeout recovers explicitly and disposal prohibits new submissions',async()=>{assert.equal(typeof api.ReferenceRenderClient,'function');const w={postMessage(){},terminate(){}},c=new api.ReferenceRenderClient({}, {workerFactory:()=>w,timeoutMs:10,fallbackFactory:()=>({render:async()=>({value:1}),dispose(){}})});const r=await c.run({});assert.equal(r.execution.mode,'main-thread-fallback');assert.match(r.execution.warnings.join(' '),/timeout/);c.dispose();await assert.rejects(()=>c.run({}),/disposed/);});
test('fatal worker promise rejection retries the same job instead of leaving a stale worker',async()=>{const w=new FakeWorker();w.postMessage=function(m){queueMicrotask(()=>this.onmessage({data:m.kind==='boot'?{kind:'ready'}:{kind:'fatal',error:'unhandled asynchronous rejection'}}));};const c=new api.ReferenceRenderClient({}, {workerFactory:()=>w,timeoutMs:100,fallbackFactory:()=>({render:async j=>({value:j.n}),dispose(){}})});const r=await c.run({n:23});assert.equal(r.value,23);assert.equal(r.execution.mode,'main-thread-fallback');assert.match(r.execution.warnings.join(' '),/unhandled asynchronous rejection/);assert.ok(w.terminated);c.dispose();});
